package run.ikaros.finance; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class FinanceCsvService{private static final String HEADER="type,accountId,targetAccountId,amount,currency,categoryId,payee,note,occurredAt,source\n";private final LedgerRepository ledgers;private final FinanceTransactionRepository transactions;private final PersistentFinanceTransactionService transactionService;public FinanceCsvService(LedgerRepository l,FinanceTransactionRepository t,PersistentFinanceTransactionService s){ledgers=l;transactions=t;transactionService=s;}public Mono<String> export(UUID a,UUID ledgerId){return own(a,ledgerId).flatMap(x->transactions.findAllByLedgerIdAndOwnerIdOrderByOccurredAtDesc(ledgerId,a).map(this::line).collectList().map(xs->HEADER+String.join("\n",xs)+(!xs.isEmpty()?"\n":"")));}public Mono<CsvImportResult> importCsv(UUID a,UUID ledgerId,String csv){return own(a,ledgerId).flatMapMany(x->reactor.core.publisher.Flux.fromArray(csv.split("\\R"))).skip(1).filter(s->!s.isBlank()).flatMap(line->parse(line).flatMap(q->transactionService.create(a,ledgerId,q)).map(x->true).onErrorReturn(false),1).collectList().map(xs->{int ok=0;for(Boolean x:xs)if(x)ok++;return new CsvImportResult(ok,xs.size()-ok);});}private Mono<LedgerEntity> own(UUID a,UUID id){return ledgers.findById(id).filter(x->x.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权访问")));}private Mono<CreateTransactionRequest> parse(String line){String[] p=line.split(",",-1);try{if(p.length<10)throw new IllegalArgumentException();return Mono.just(new CreateTransactionRequest(TransactionType.valueOf(p[0]),UUID.fromString(p[1]),emptyUuid(p[2]),new BigDecimal(p[3]),empty(p[4]),emptyUuid(p[5]),empty(p[6]),empty(p[7]),Instant.parse(p[8]),empty(p[9])));}catch(Exception e){return Mono.error(new IllegalArgumentException("CSV 行格式无效"));}}private UUID emptyUuid(String s){return s==null||s.isBlank()?null:UUID.fromString(s);}private String empty(String s){return s==null||s.isBlank()?null:s;}private String line(FinanceTransactionEntity x){return String.join(",",x.type().name(),x.accountId().toString(),x.targetAccountId()==null?"":x.targetAccountId().toString(),x.amount().toPlainString(),x.currency(),x.categoryId()==null?"":x.categoryId().toString(),csv(x.payee()),csv(x.note()),x.occurredAt().toString(),csv(x.source()));}private String csv(String s){return s==null?"":"\""+s.replace("\"","\"\"")+"\"";}}
